/*
 * Campo de imagem do perfil (capa ou fundo do cartão): prévia, envio de
 * arquivo e, como alternativa, o endereço https de uma imagem.
 *
 * O envio vai na hora para a rota própria (`/users/{id}/canela-<tipo>`), como
 * o avatar do core; o endereço segue com o resto do formulário, no "Salvar".
 */
import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import { t } from '../../utils/settings';
import { coverUploadEnabled, cssImage, externalImagesEnabled } from './data';
/** O mesmo teto do servidor (ProfileImageValidator), para avisar antes de enviar 4 MB à toa. */
const MAX_BYTES = 4096 * 1024;
const ACCEPT = 'image/jpeg,image/png,image/gif,image/webp';
export default class ImageField extends Component {
  loading = false;
  view() {
    const {
      kind,
      label,
      help,
      value
    } = this.attrs;
    const id = `CanelaProfile-${kind}`;
    const preview = /^https?:\/\//i.test(value) ? value : null;
    return m("div", {
      className: `Form-group CanelaProfileImage CanelaProfileImage--${kind}`
    }, m("label", {
      for: id
    }, label), m("div", {
      className: `CanelaProfileImage-preview${preview ? ' has-image' : ''}`,
      style: preview ? {
        backgroundImage: cssImage(preview)
      } : undefined,
      "aria-hidden": "true"
    }, !preview && m("span", {
      className: "CanelaProfileImage-empty"
    }, t('profile.settings.no_image'))), m("div", {
      className: "CanelaProfileImage-controls"
    }, coverUploadEnabled() && m(Button, {
      className: "Button",
      icon: "fas fa-upload",
      loading: this.loading,
      onclick: () => this.pick()
    }, t('profile.settings.upload')), preview && m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-trash",
      "aria-label": t('profile.settings.remove_image'),
      title: t('profile.settings.remove_image'),
      disabled: this.loading,
      onclick: () => this.remove()
    })), externalImagesEnabled() && m("input", {
      id: id,
      className: "FormControl",
      type: "url",
      inputmode: "url",
      maxlength: 255,
      placeholder: "https://",
      value: value,
      oninput: event => this.attrs.oninput(event.target.value)
    }), help && m("p", {
      className: "helpText"
    }, help));
  }
  pick() {
    if (this.loading) return;
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = ACCEPT;
    input.onchange = () => {
      const file = input.files?.[0];
      if (file) this.upload(file);
    };
    input.click();
  }
  upload(file) {
    if (file.size > MAX_BYTES) {
      app.alerts.show({
        type: 'error'
      }, t('profile.settings.image_too_large', {
        max: '4 MB'
      }));
      return;
    }
    const body = new FormData();
    body.append('image', file);
    this.send('POST', body);
  }
  remove() {
    if (this.attrs.value && !this.isStoredFile()) {
      // Só um endereço digitado e ainda não salvo: basta limpar o campo.
      this.attrs.oninput('');
      return;
    }
    this.send('DELETE');
  }

  /** A imagem atual veio de um envio (arquivo no fórum) e não de um endereço externo. */
  isStoredFile() {
    const stored = this.storedValue();
    return !!stored && stored === this.attrs.value;
  }
  storedValue() {
    const attribute = this.attrs.kind === 'cover' ? 'canelaCoverUrl' : 'canelaCardBackgroundUrl';
    return this.attrs.user.attribute(attribute) || '';
  }
  send(method, body) {
    const user = this.attrs.user;
    this.loading = true;
    m.redraw();
    app.request({
      method,
      url: `${app.forum.attribute('apiUrl')}/users/${user.id()}/canela-${this.attrs.kind}`,
      // FormData vai como está; o core serializaria em JSON.
      ...(body ? {
        serialize: raw => raw,
        body
      } : {})
    }).then(payload => {
      app.store.pushPayload(payload);
      this.attrs.onstored(this.storedValue());
    }).catch(() => {
      // O core já mostra o erro da API num alerta.
    }).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ramon-canela', 'forum/features/profile/ImageField', ImageField);